CREATE TABLE "del_order_events" (
	"id" uuid PRIMARY KEY NOT NULL,
	"account_id" uuid NOT NULL,
	"order_id" uuid NOT NULL,
	"type" text NOT NULL,
	"from_status" text,
	"to_status" text,
	"actor_type" text NOT NULL,
	"actor_id" uuid,
	"device_id" uuid,
	"client_ts" timestamp with time zone,
	"server_ts" timestamp with time zone DEFAULT now() NOT NULL,
	"idempotency_key" uuid,
	"point" geometry(Point,4326),
	"reason_code" text,
	"note" text,
	"payload" jsonb DEFAULT '{}'::jsonb NOT NULL,
	CONSTRAINT "del_order_events_type_check" CHECK ("del_order_events"."type" IN ('transition', 'note')),
	CONSTRAINT "del_order_events_from_status_check" CHECK ("del_order_events"."from_status" IN ('pending', 'accepted', 'offered', 'assigned', 'picked_up', 'out_for_delivery', 'attempted', 'delivered', 'failed', 'returned', 'cancelled')),
	CONSTRAINT "del_order_events_to_status_check" CHECK ("del_order_events"."to_status" IN ('pending', 'accepted', 'offered', 'assigned', 'picked_up', 'out_for_delivery', 'attempted', 'delivered', 'failed', 'returned', 'cancelled')),
	CONSTRAINT "del_order_events_transition_check" CHECK (("del_order_events"."type" = 'transition') = ("del_order_events"."to_status" IS NOT NULL)),
	CONSTRAINT "del_order_events_actor_type_check" CHECK ("del_order_events"."actor_type" IN ('user', 'driver', 'system', 'api_key')),
	CONSTRAINT "del_order_events_reason_code_check" CHECK (char_length("del_order_events"."reason_code") <= 40),
	CONSTRAINT "del_order_events_note_check" CHECK (char_length("del_order_events"."note") <= 1000)
);
