	CONSTRAINT "del_order_items_name_en_check" CHECK (char_length("del_order_items"."name_en") BETWEEN 1 AND 200),
	CONSTRAINT "del_order_items_sku_check" CHECK (char_length("del_order_items"."sku") BETWEEN 1 AND 120),
	CONSTRAINT "del_order_items_quantity_check" CHECK ("del_order_items"."quantity" BETWEEN 1 AND 9999),
	CONSTRAINT "del_order_items_direction_check" CHECK ("del_order_items"."direction" IN ('out', 'in')),
	CONSTRAINT "del_order_items_declared_value_check" CHECK ("del_order_items"."declared_value" >= 0),
	CONSTRAINT "del_order_items_currency_check" CHECK ("del_order_items"."currency" = 'SAR')
);
