	CONSTRAINT "del_orders_recipient_name_check" CHECK (char_length("del_orders"."recipient_name") BETWEEN 1 AND 200),
	CONSTRAINT "del_orders_recipient_phone_check" CHECK ("del_orders"."recipient_phone" ~ '^\+[1-9][0-9]{7,14}$'),
