	CONSTRAINT "del_orders_geocode_confidence_check" CHECK ("del_orders"."geocode_confidence" BETWEEN 0 AND 1),
	CONSTRAINT "del_orders_cod_amount_check" CHECK ("del_orders"."cod_amount" >= 0 AND ("del_orders"."cod_amount" = 0 OR "del_orders"."kind" IN ('delivery', 'exchange'))),
	CONSTRAINT "del_orders_currency_check" CHECK ("del_orders"."currency" = 'SAR'),
	CONSTRAINT "del_orders_executor_account_id_check" CHECK ("del_orders"."executor_account_id" IS NULL),
	CONSTRAINT "del_orders_attempt_count_check" CHECK ("del_orders"."attempt_count" >= 0),
	CONSTRAINT "del_orders_max_attempts_check" CHECK ("del_orders"."max_attempts" >= 1),
